property.value:
let $skip := '^(ignored?|unused|dummy|_.*)$',
    $takeFirst := function($loop) {
      exists($loop/*[last()][self::BreakStatement or self::ReturnStatement]
             | $loop/*[last()][self::Block]/*[last()][self::BreakStatement or self::ReturnStatement])
    },
    $unconditional := function($e, $loop) {
      empty($e/ancestor::*[self::IfStatement or self::ConditionalExpression][ancestor::*[. is $loop]])
    },
    $fixed := function($e, $xs) {
      exists($e[self::ArrayAccess][*[1][self::VariableAccess or self::FieldAccess][@Name = $xs]][*[2][self::NumericLiteral]]
             | $e[self::MethodCall][@MethodName = 'get'][ArgumentList/@Size = 1][ArgumentList/NumericLiteral]
                 [*[1][self::VariableAccess or self::FieldAccess][@Name = $xs]]
                 [*[1][pmd-java:typeIs('java.util.List')]])
    }
return (
  for $loop in //ForeachStatement[let $x := LocalVariableDeclaration/VariableDeclarator/VariableId/@Name
      return not(matches($x, $skip)) and not(*[3]//VariableAccess[@Name = $x])]
        [*[2][self::VariableAccess or self::FieldAccess]][not($takeFirst(.))]
  return $loop/*[3]//*[self::ArrayAccess or self::MethodCall][$fixed(., $loop/*[2]/@Name)][$unconditional(., $loop)],
  for $loop in //ForStatement[ForInit/LocalVariableDeclaration/VariableDeclarator/VariableId/@Name = InfixExpression[@Operator = '<']/*[1]/@Name]
      [let $i := ForInit//VariableId/@Name return not(*[last()]//VariableAccess[@Name = $i])]
      [not($takeFirst(.))]
  return let $limit := $loop/InfixExpression[@Operator = '<']/*[2],
      $xs := ($limit[self::MethodCall][@MethodName = 'size'][ArgumentList/@Size = 0]/*[1][self::VariableAccess or self::FieldAccess]
              | $limit[self::FieldAccess][@Name = 'length']/*[1][self::VariableAccess or self::FieldAccess])/@Name
    return $loop/*[last()]//*[self::ArrayAccess or self::MethodCall][exists($xs)][$fixed(., $xs)][$unconditional(., $loop)]
)
